if (!function_exists('se_mark')) {
    /** The Soft Engine logomark (S + orbit). $uid keeps gradient ids unique per copy on a page. */
    function se_mark($uid)
    {
        return '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true" focusable="false">'
            . '<defs><linearGradient id="' . $uid . 'g" x1="8" y1="6" x2="40" y2="42" gradientUnits="userSpaceOnUse">'
            . '<stop stop-color="#1f7bff"/><stop offset="1" stop-color="#3de0ff"/></linearGradient></defs>'
            . '<rect x="3" y="3" width="42" height="42" rx="13" fill="#0b1426" stroke="url(#' . $uid . 'g)" stroke-opacity=".55"/>'
            . '<path d="M30.5 16.2c-1.5-1.8-3.8-2.9-6.6-2.9-4 0-6.8 2.1-6.8 5.2 0 7 13.6 3.8 13.6 10.6 0 3.2-2.9 5.5-7.1 5.5-3 0-5.7-1.2-7.4-3.3" stroke="url(#' . $uid . 'g)" stroke-width="3.6" stroke-linecap="round"/>'
            . '<g class="orbit"><ellipse cx="24" cy="24" rx="21" ry="8.5" transform="rotate(-28 24 24)" stroke="#ff8a1f" stroke-opacity=".75" stroke-width="1.3"/>'
            . '<circle cx="42.5" cy="14.1" r="2.6" fill="#ff8a1f"/></g>'
            . '</svg>';
    }
}
